mapper.select:
SELECT f.*, u.nickname AS create_by_name, c.name AS customer_name,
       CASE f.target_type WHEN 'LEAD' THEN l.company WHEN 'OPPORTUNITY' THEN o.name ELSE c.name END AS target_name
FROM crm_followup f
LEFT JOIN sys_user u ON u.id = f.create_by
LEFT JOIN scm_customer c ON c.id = f.customer_id
LEFT JOIN crm_lead l ON f.target_type = 'LEAD' AND l.id = f.target_id
LEFT JOIN crm_opportunity o ON f.target_type = 'OPPORTUNITY' AND o.id = f.target_id

    f.target_type = #{targetType}
    AND f.target_id = #{targetId}
    AND f.customer_id = #{customerId}
    AND f.create_by = #{userId}
    AND f.method = #{method}
    AND f.follow_time >= #{begin}
    AND f.follow_time < #{end}

ORDER BY f.follow_time DESC, f.id DESC
